int
setuid(uid_t id)
{
	int result;

	ENTER();

	SHOWVALUE(id);

	assert(__UserGroupBase != NULL);

	if(__root_mode)
	{
		__root_uid = id;

		result = OK;
	}
	else
	{
		PROFILE_OFF();
		result = __setuid((LONG)id);
		PROFILE_ON();
	}

	if(__check_abort_enabled)
		__check_abort();

	RETURN(result);
	return(result);
}

